import numpy as np
import pandas as pd

from backtest import xgb_walk_forward_loop, summarize_backtest

# File generated by claude code to test what xgb model gets wrong, and where it goes wrong. The first conclusion is
# obviously overfitting as generally expected.

def calibration_curve(records: pd.DataFrame, outcome: str, n_bins: int = 10) -> pd.DataFrame:
    """Reliability diagram data: for each bin of predicted probability, the mean predicted
    probability vs the actual frequency of that outcome. A well-calibrated model tracks the
    diagonal; points above the diagonal mean the model is underconfident there, below means
    overconfident (dangerous when probabilities feed Kelly staking)."""
    prob_col = {'Home': 'prob_home', 'Draw': 'prob_draw', 'Away': 'prob_away'}[outcome]
    df = records[[prob_col, 'actual_outcome']].copy()
    df['bin'] = pd.qcut(df[prob_col], n_bins, duplicates='drop')

    grouped = df.groupby('bin', observed=True).agg(
        predicted=(prob_col, 'mean'),
        actual=('actual_outcome', lambda s: (s == outcome).mean()),
        n=('actual_outcome', 'size'),
    ).reset_index(drop=True)

    return grouped


def log_loss_by_margin(records: pd.DataFrame) -> pd.DataFrame:
    """Model vs market log loss bucketed by final goal margin, to test whether lopsided
    (blowout) results are where the model falls down relative to the market."""
    df = records.copy()
    df['margin_bucket'] = pd.cut(
        df['margin'], bins=[0, 1, 2, 3, 100], labels=['0', '1', '2', '3+'], right=False
    )

    return df.groupby('margin_bucket', observed=True).agg(
        model_log_loss=('model_log_loss', 'mean'),
        market_log_loss=('market_log_loss', 'mean'),
        n=('margin', 'size'),
    ).reset_index()


def bet_hit_rate_by_edge(records: pd.DataFrame, n_bins: int = 5) -> pd.DataFrame:
    """Bets bucketed by claimed edge over the market. If bigger 'edges' don't translate into
    higher realized win rates, the edge is model noise, not signal -- and Kelly is sizing up
    on that noise."""
    bets = records[records['bet_placed']].copy()
    bets['edge_bin'] = pd.qcut(bets['best_edge'], n_bins, duplicates='drop')
    bets['predicted_prob'] = bets.apply(lambda r: r[f"prob_{r['best_outcome'].lower()}"], axis=1)
    bets['won'] = bets['actual_outcome'] == bets['best_outcome']

    return bets.groupby('edge_bin', observed=True).agg(
        mean_edge=('best_edge', 'mean'),
        predicted_win_prob=('predicted_prob', 'mean'),
        actual_win_rate=('won', 'mean'),
        n_bets=('won', 'size'),
        total_profit=('profit', 'sum'),
    ).reset_index()


def profit_over_time(records: pd.DataFrame) -> pd.DataFrame:
    """Cumulative profit by bet date, to see whether losses are spread evenly or concentrated
    in a specific stretch (a regime shift, one bad run of blowouts, etc.)."""
    bets = records[records['bet_placed']].sort_values('date').copy()
    bets['cum_profit'] = bets['profit'].cumsum()
    return bets[['date', 'profit', 'cum_profit', 'margin', 'best_outcome', 'actual_outcome']]


def param_sensitivity(
        matches_df: pd.DataFrame,
        training_days_list,
        retrain_every_n_days_list,
        min_edge: float = 0.02,
        balance: float = 1000,
) -> pd.DataFrame:
    """Runs the walk-forward backtest across a grid of (training_days, retrain_every_n_days)
    and reports log loss alongside ROI. Log loss is the honest signal -- it doesn't depend on
    the betting threshold/staking heuristic. ROI on ~a few hundred bets is a noisy statistic;
    treat the single best ROI cell in this grid as likely luck, not a config to lock in."""
    rows = []
    for training_days in training_days_list:
        for retrain_every_n_days in retrain_every_n_days_list:
            records = xgb_walk_forward_loop(
                matches_df,
                training_days=training_days,
                retrain_every_n_days=retrain_every_n_days,
                min_edge=min_edge,
                balance=balance,
            )
            if records.empty:
                continue
            summary = summarize_backtest(records, starting_balance=balance)
            rows.append({
                'training_days': training_days,
                'retrain_every_n_days': retrain_every_n_days,
                **summary,
            })

    return pd.DataFrame(rows)
